    mtimeMs: number,
    entries: SearchableEntry[],
    sessionTitle: string | undefined
  ): void {
    // If already exists, delete first to update position
    this.cache.delete(filePath);

    // Evict oldest if at capacity
    if (this.cache.size >= this.maxSize) {
