function getCachedRegex(pattern: string, flags: string): RegExp | null {
  const key = `${pattern}\0${flags}`;
  if (regexCache.has(key)) {
    return regexCache.get(key) ?? null;
  }

  // Evict oldest entries when cache is full
  if (regexCache.size >= MAX_CACHE_SIZE) {
    const firstKey = regexCache.keys().next().value;
    if (firstKey !== undefined) {
      regexCache.delete(firstKey);
    }
  }

  const regex = createSafeRegExp(pattern, flags);
  regexCache.set(key, regex);
  return regex;
}

function matchesPattern(content: string, pattern: string): boolean {
  const regex = getCachedRegex(pattern, 'i');
  if (!regex) {
    // Pattern is invalid or potentially dangerous, reject match
    return false;
  }
  return regex.test(content);
}

function matchesIgnorePatterns(content: string, ignorePatterns?: string[]): boolean {
  if (!ignorePatterns || ignorePatterns.length === 0) {
    return false;
  }

  for (const pattern of ignorePatterns) {
    const regex = getCachedRegex(pattern, 'i');
    if (regex?.test(content)) {
      return true;
    }
    // Invalid or potentially dangerous patterns are skipped
  }

  return false;
}

function extractToolUseField(
  toolUse: { name: string; input?: Record<string, unknown> },
  matchField?: string
): string | null {
  if (!matchField || !toolUse.input) return null;

  const value = toolUse.input[matchField];
  if (typeof value === 'string') {
    return value;
  }
  if (value !== undefined) {
    return JSON.stringify(value);
  }
  return null;
}

function getContentBlocks(message: ParsedMessage): ContentBlock[] {
  if (Array.isArray(message.content)) {
    return message.content;
  }
  return [];
}

