  hiddenSessions: Record<string, { sessionId: string; hiddenAt: number }[]>;
}

interface SshPersistConfig {
  lastConnection: {
    host: string;
    port: number;
    username: string;
    authMethod: 'password' | 'sshConfig';
    privateKeyPath?: string;
  } | null;
  autoReconnect: boolean;
