      const refMatch = /^ref:\s*refs\/heads\/(.+)$/.exec(headContent);
      if (refMatch) {
        return refMatch[1];
      }

      // HEAD is detached (commit hash)
      return 'detached HEAD';
    } catch (error) {
      logger.error(`Error reading git branch for ${projectPath}:`, error);
      return null;
    }
  }

