function translateWslMountPath(posixPath: string): string {
  if (process.platform !== 'win32') {
    return posixPath;
  }
  const match = /^\/mnt\/([a-zA-Z])(\/.*)?$/.exec(posixPath);
  if (match) {
    const drive = match[1].toUpperCase();
    const rest = match[2] ?? '';
    return `${drive}:${rest}`;
  }
  return posixPath;
}

