interface UseAddTriggerFormHandlersOptions {
  formState: AddTriggerFormStateReturn;
  validatePattern: (pattern: string) => boolean;
  clearPreview: () => void;
}

interface AddTriggerFormHandlersReturn {
  handleModeChange: (newMode: TriggerMode) => void;
  handleContentTypeChange: (newContentType: TriggerContentType) => void;
  handleToolNameChange: (newToolName: string) => void;
  handleAddRepository: (item: RepositoryDropdownItem) => void;
  handleRemoveIgnorePattern: (idx: number) => void;
  handleAddIgnorePattern: (pattern: string) => void;
  handleRemoveRepository: (idx: number) => void;
  handleMatchPatternChange: (value: string) => void;
  handleTokenThresholdChange: (value: string) => void;
  handleCancel: () => void;
  buildNewTrigger: (generateId: () => string) => Omit<NotificationTrigger, 'isBuiltin'>;
}

function useAddTriggerFormHandlers({
  formState,
  validatePattern,
  clearPreview,
}: UseAddTriggerFormHandlersOptions): AddTriggerFormHandlersReturn {
  const {
    name,
    toolName,
    mode,
    contentType,
    matchField,
    matchPattern,
    tokenThreshold,
    tokenType,
    ignorePatterns,
    repositoryIds,
    color,
    setMode,
    setContentType,
    setToolName,
    setMatchField,
    setMatchPattern,
    setTokenThreshold,
    setIgnorePatterns,
    setRepositoryIds,
    setIsExpanded,
    resetForm,
  } = formState;

  // When mode changes, adjust content type defaults
  const handleModeChange = useCallback(
    (newMode: TriggerMode) => {
      setMode(newMode);
      if (newMode === 'error_status') {
        setContentType('tool_result');
      }
    },
    [setMode, setContentType]
  );

  // When content type changes, reset matchField to first available option
  const handleContentTypeChange = useCallback(
    (newContentType: TriggerContentType) => {
      setContentType(newContentType);
      const newMatchFields = getAvailableMatchFields(newContentType, toolName || undefined);
      setMatchField(newMatchFields[0]?.value || '');
      // Reset tool name if not applicable
      if (newContentType !== 'tool_use' && newContentType !== 'tool_result') {
        setToolName('');
      }
    },
    [toolName, setContentType, setMatchField, setToolName]
  );

  // When tool name changes, reset matchField to first available option
  const handleToolNameChange = useCallback(
    (newToolName: string) => {
      setToolName(newToolName);
      const newMatchFields = getAvailableMatchFields(contentType, newToolName || undefined);
      setMatchField(newMatchFields[0]?.value || '');
    },
    [contentType, setToolName, setMatchField]
  );

  // Handler for adding repository
  const handleAddRepository = useCallback(
    (item: RepositoryDropdownItem) => {
      if (!repositoryIds.includes(item.id)) {
        setRepositoryIds([...repositoryIds, item.id]);
      }
    },
    [repositoryIds, setRepositoryIds]
  );

  // Handler for removing ignore pattern
  const handleRemoveIgnorePattern = useCallback(
    (idx: number) => {
      const newPatterns = [...ignorePatterns];
      newPatterns.splice(idx, 1);
      setIgnorePatterns(newPatterns);
    },
    [ignorePatterns, setIgnorePatterns]
  );

  // Handler for adding ignore pattern
  const handleAddIgnorePattern = useCallback(
    (pattern: string) => {
      setIgnorePatterns([...ignorePatterns, pattern]);
    },
    [ignorePatterns, setIgnorePatterns]
  );

  // Handler for removing repository
  const handleRemoveRepository = useCallback(
    (idx: number) => {
      const newIds = [...repositoryIds];
      newIds.splice(idx, 1);
      setRepositoryIds(newIds);
    },
    [repositoryIds, setRepositoryIds]
  );

  // Handler for match pattern change with validation
  const handleMatchPatternChange = useCallback(
    (value: string) => {
      setMatchPattern(value);
      validatePattern(value);
    },
    [setMatchPattern, validatePattern]
  );

  // Handler for token threshold change
  const handleTokenThresholdChange = useCallback(
    (value: string) => {
      const val = value.replace(/\D/g, '');
      setTokenThreshold(parseInt(val) || 0);
    },
    [setTokenThreshold]
  );

  // Handler for cancel button
  const handleCancel = useCallback(() => {
    resetForm();
    clearPreview();
    setIsExpanded(false);
  }, [resetForm, clearPreview, setIsExpanded]);

  // Build new trigger object from form state
  const buildNewTrigger = useCallback(
    (generateId: () => string): Omit<NotificationTrigger, 'isBuiltin'> => {
      return {
        id: `custom-${generateId()}`,
        name: name.trim(),
        enabled: true,
        contentType,
        mode,
        ...(mode === 'error_status' && { requireError: true }),
        ...(mode === 'content_match' &&
          matchField && { matchField: matchField as TriggerMatchField }),
        ...(mode === 'content_match' && matchPattern && { matchPattern }),
        ...(mode === 'token_threshold' && { tokenThreshold, tokenType }),
        ...((contentType === 'tool_use' || contentType === 'tool_result') &&
          toolName && { toolName }),
        ...(ignorePatterns.length > 0 && { ignorePatterns }),
        ...(repositoryIds.length > 0 && { repositoryIds }),
        color,
      };
    },
    [
      name,
      contentType,
      mode,
      matchField,
      matchPattern,
      tokenThreshold,
      tokenType,
      toolName,
      ignorePatterns,
      repositoryIds,
      color,
    ]
  );

  return {
    handleModeChange,
    handleContentTypeChange,
    handleToolNameChange,
    handleAddRepository,
    handleRemoveIgnorePattern,
    handleAddIgnorePattern,
    handleRemoveRepository,
    handleMatchPatternChange,
    handleTokenThresholdChange,
    handleCancel,
    buildNewTrigger,
  };
}

interface AddTriggerFormState {
  // Section 1: General Info
  name: string;
  toolName: string;

  // Section 2: Trigger Condition
  mode: TriggerMode;

  // Section 3: Dynamic Configuration
  // Content match settings
  contentType: TriggerContentType;
  matchField: string;
  matchPattern: string;

  // Token threshold settings
  tokenThreshold: number;
  tokenType: TriggerTokenType;

  // Section 4: Advanced
  ignorePatterns: string[];

  // Section 5: Repository Scope
  repositoryIds: string[];

  // Display
  color: TriggerColor;

  // UI state
  isExpanded: boolean;
}

interface AddTriggerFormStateReturn extends AddTriggerFormState {
  setName: (name: string) => void;
  setToolName: (toolName: string) => void;
  setMode: (mode: TriggerMode) => void;
  setContentType: (contentType: TriggerContentType) => void;
  setMatchField: (matchField: string) => void;
  setMatchPattern: (matchPattern: string) => void;
  setTokenThreshold: (threshold: number) => void;
  setTokenType: (tokenType: TriggerTokenType) => void;
  setIgnorePatterns: (patterns: string[]) => void;
  setRepositoryIds: (ids: string[]) => void;
  setColor: (color: TriggerColor) => void;
  setIsExpanded: (expanded: boolean) => void;
  resetForm: () => void;
}

function useAddTriggerFormState(): AddTriggerFormStateReturn {
  // Section 1: General Info
  const [name, setName] = useState('');
  const [toolName, setToolName] = useState<string>('');

  // Section 2: Trigger Condition
  const [mode, setMode] = useState<TriggerMode>('error_status');

  // Section 3: Dynamic Configuration
  // Content match settings
  const [contentType, setContentType] = useState<TriggerContentType>('tool_result');
  const [matchField, setMatchField] = useState<string>('content');
  const [matchPattern, setMatchPattern] = useState('');

  // Token threshold settings
  const [tokenThreshold, setTokenThreshold] = useState<number>(1000);
  const [tokenType, setTokenType] = useState<TriggerTokenType>('total');

  // Section 4: Advanced
  const [ignorePatterns, setIgnorePatterns] = useState<string[]>([]);

  // Section 5: Repository Scope
  const [repositoryIds, setRepositoryIds] = useState<string[]>([]);

  // Display
  const [color, setColor] = useState<TriggerColor>('red');

  // UI state
  const [isExpanded, setIsExpanded] = useState(false);

  const resetForm = useCallback(() => {
    setName('');
    setToolName('');
    setMode('error_status');
    setContentType('tool_result');
    setMatchField('content');
    setMatchPattern('');
    setTokenThreshold(1000);
    setTokenType('total');
    setIgnorePatterns([]);
    setRepositoryIds([]);
    // Intentionally do NOT reset color — preserve last-used color across triggers
  }, []);

  return {
    // State values
    name,
    toolName,
    mode,
    contentType,
    matchField,
    matchPattern,
    tokenThreshold,
    tokenType,
    ignorePatterns,
    repositoryIds,
    color,
    isExpanded,

    // Setters
    setName,
    setToolName,
    setMode,
    setContentType,
    setMatchField,
    setMatchPattern,
    setTokenThreshold,
    setTokenType,
    setIgnorePatterns,
    setRepositoryIds,
    setColor,
    setIsExpanded,
    resetForm,
  };
}

function useRepositoryLookup(repositoryIds: string[]): RepositoryDropdownItem[] {
  const repositoryGroups = useStore((state) => state.repositoryGroups);

  return useMemo((): RepositoryDropdownItem[] => {
    const items: RepositoryDropdownItem[] = [];

    for (const repositoryId of repositoryIds) {
      // Find repository group by ID
      const group = repositoryGroups.find((g) => g.id === repositoryId);
      if (group) {
        items.push({
          id: group.id,
          name: group.name,
          path: group.worktrees[0]?.path ?? '',
          worktreeCount: group.worktrees.length,
          totalSessions: group.totalSessions,
        });
      } else {
        // If not found, create a placeholder item
        items.push({
          id: repositoryId,
          name: repositoryId,
          path: '',
          worktreeCount: 0,
          totalSessions: 0,
        });
      }
    }

    return items;
  }, [repositoryIds, repositoryGroups]);
}

interface UseTriggerCardStateOptions {
  trigger: NotificationTrigger;
  onUpdate: (updates: Partial<NotificationTrigger>) => Promise<void>;
  validatePattern: (pattern: string) => boolean;
}

interface UseTriggerCardStateReturn {
  // UI state
  isExpanded: boolean;
  setIsExpanded: (value: boolean) => void;
  editingName: boolean;
  setEditingName: (value: boolean) => void;

  // Local form values
  localName: string;
  setLocalName: (value: string) => void;
  localPattern: string;
  localMode: TriggerMode;
  localTokenThreshold: number;
  localTokenType: TriggerTokenType;

  // Handlers
  handleToggleEnabled: () => void;
  handleNameSave: () => void;
  handlePatternBlur: () => void;
  handlePatternChange: (value: string) => void;
  handleContentTypeChange: (value: TriggerContentType) => void;
  handleToolNameChange: (value: string) => void;
  handleMatchFieldChange: (value: string) => void;
  handleModeChange: (newMode: TriggerMode) => void;
  handleTokenThresholdChange: (value: number) => void;
  handleTokenThresholdBlur: () => void;
  handleTokenTypeChange: (value: TriggerTokenType) => void;
  handleAddIgnorePattern: (pattern: string) => void;
  handleRemoveIgnorePattern: (index: number) => void;
  handleAddRepository: (item: RepositoryDropdownItem) => void;
  handleRemoveRepository: (index: number) => void;
  handleColorChange: (color: TriggerColor) => void;
}

function useTriggerCardState({
  trigger,
  onUpdate,
  validatePattern,
}: UseTriggerCardStateOptions): UseTriggerCardStateReturn {
  // UI state
  const [isExpanded, setIsExpanded] = useState(false);
  const [editingName, setEditingName] = useState(false);

  // Local form values
  const [localName, setLocalName] = useState(trigger.name);
  const [localPattern, setLocalPattern] = useState(trigger.matchPattern ?? '');
  const [localMode, setLocalMode] = useState<TriggerMode>(deriveMode(trigger));
  const [localTokenThreshold, setLocalTokenThreshold] = useState<number>(
    trigger.tokenThreshold ?? 1000
  );
  const [localTokenType, setLocalTokenType] = useState<TriggerTokenType>(
    trigger.tokenType ?? 'total'
  );

  // Toggle enabled/disabled
  const handleToggleEnabled = useCallback(() => {
    void onUpdate({ enabled: !trigger.enabled });
  }, [trigger.enabled, onUpdate]);

  // Save name on blur or Enter
  const handleNameSave = useCallback(() => {
    if (localName.trim() && localName !== trigger.name) {
      void onUpdate({ name: localName.trim() });
    }
    setEditingName(false);
  }, [localName, trigger.name, onUpdate]);

  // Save pattern on blur
  const handlePatternBlur = useCallback(() => {
    if (validatePattern(localPattern) && localPattern !== trigger.matchPattern) {
      void onUpdate({ matchPattern: localPattern });
    }
  }, [localPattern, trigger.matchPattern, onUpdate, validatePattern]);

  // Update local pattern and validate
  const handlePatternChange = useCallback(
    (value: string) => {
      setLocalPattern(value);
      validatePattern(value);
    },
    [validatePattern]
  );

  // Content type change - reset matchField to first available
  const handleContentTypeChange = useCallback(
    (value: TriggerContentType) => {
      const newMatchFields = getAvailableMatchFields(value, trigger.toolName ?? undefined);
      const newMatchField = newMatchFields[0]?.value ?? '';
      const updates: Partial<NotificationTrigger> = {
        contentType: value,
        matchField: (newMatchField as TriggerMatchField) || undefined,
      };
      // Reset tool name if not applicable
      if (value !== 'tool_use' && value !== 'tool_result') {
        updates.toolName = undefined;
      }
      void onUpdate(updates);
    },
    [onUpdate, trigger.toolName]
  );

  // Tool name change - reset matchField to first available
  const handleToolNameChange = useCallback(
    (value: string) => {
      const newMatchFields = getAvailableMatchFields(trigger.contentType, value || undefined);
      const newMatchField = newMatchFields[0]?.value ?? '';
      void onUpdate({
        toolName: value || undefined,
        matchField: (newMatchField as TriggerMatchField) || undefined,
      });
    },
    [onUpdate, trigger.contentType]
  );

  // Match field change
  const handleMatchFieldChange = useCallback(
    (value: string) => {
      void onUpdate({ matchField: value as TriggerMatchField });
    },
    [onUpdate]
  );

  // Mode change with appropriate defaults
  const handleModeChange = useCallback(
    (newMode: TriggerMode) => {
      setLocalMode(newMode);
      const updates: Partial<NotificationTrigger> = { mode: newMode };

      if (newMode === 'error_status') {
        updates.requireError = true;
        updates.contentType = 'tool_result';
      } else if (newMode === 'content_match') {
        // Ensure matchField is set for validation
        const contentType = trigger.contentType ?? 'tool_result';
        const matchFields = getAvailableMatchFields(contentType, trigger.toolName ?? undefined);
        if (!trigger.matchField && matchFields.length > 0) {
          updates.matchField = matchFields[0].value as TriggerMatchField;
        }
      } else if (newMode === 'token_threshold') {
        updates.tokenThreshold = localTokenThreshold;
        updates.tokenType = localTokenType;
      }

      void onUpdate(updates);
    },
    [
      onUpdate,
      localTokenThreshold,
      localTokenType,
      trigger.contentType,
      trigger.toolName,
      trigger.matchField,
    ]
  );

  // Token threshold change — local only, commit on blur
  const handleTokenThresholdChange = useCallback((value: number) => {
    setLocalTokenThreshold(value);
  }, []);

  // Commit token threshold to config
  const handleTokenThresholdBlur = useCallback(() => {
    if (localTokenThreshold !== (trigger.tokenThreshold ?? 1000)) {
      void onUpdate({ tokenThreshold: localTokenThreshold });
    }
  }, [localTokenThreshold, trigger.tokenThreshold, onUpdate]);

  // Token type change
  const handleTokenTypeChange = useCallback(
    (value: TriggerTokenType) => {
      setLocalTokenType(value);
      void onUpdate({ tokenType: value });
    },
    [onUpdate]
  );

  // Add ignore pattern
  const handleAddIgnorePattern = useCallback(
    (pattern: string) => {
      const newPatterns = [...(trigger.ignorePatterns ?? []), pattern];
      void onUpdate({ ignorePatterns: newPatterns });
    },
    [trigger.ignorePatterns, onUpdate]
  );

  // Remove ignore pattern
  const handleRemoveIgnorePattern = useCallback(
    (index: number) => {
      const newPatterns = [...(trigger.ignorePatterns ?? [])];
      newPatterns.splice(index, 1);
      void onUpdate({ ignorePatterns: newPatterns });
    },
    [trigger.ignorePatterns, onUpdate]
  );

  // Add repository
  const handleAddRepository = useCallback(
    (item: RepositoryDropdownItem) => {
      const currentIds = trigger.repositoryIds ?? [];
      if (!currentIds.includes(item.id)) {
        void onUpdate({ repositoryIds: [...currentIds, item.id] });
      }
    },
    [trigger.repositoryIds, onUpdate]
  );

  // Remove repository
  const handleRemoveRepository = useCallback(
    (index: number) => {
      const newIds = [...(trigger.repositoryIds ?? [])];
      newIds.splice(index, 1);
      void onUpdate({ repositoryIds: newIds });
    },
    [trigger.repositoryIds, onUpdate]
  );

  // Color change
  const handleColorChange = useCallback(
    (color: TriggerColor) => {
      void onUpdate({ color });
    },
    [onUpdate]
  );

  return {
    isExpanded,
    setIsExpanded,
    editingName,
    setEditingName,
    localName,
    setLocalName,
    localPattern,
    localMode,
    localTokenThreshold,
    localTokenType,
    handleToggleEnabled,
    handleNameSave,
    handlePatternBlur,
    handlePatternChange,
    handleContentTypeChange,
    handleToolNameChange,
    handleMatchFieldChange,
    handleModeChange,
    handleTokenThresholdChange,
    handleTokenThresholdBlur,
    handleTokenTypeChange,
    handleAddIgnorePattern,
    handleRemoveIgnorePattern,
    handleAddRepository,
    handleRemoveRepository,
    handleColorChange,
  };
}

interface UseTriggerFormOptions {
  /** Initial trigger for editing mode, or undefined for new trigger creation */
  trigger?: NotificationTrigger;
  /** Callback when trigger is updated (for edit mode) */
  onUpdate?: (updates: Partial<NotificationTrigger>) => Promise<void>;
}

interface UseTriggerFormReturn {
  // Pattern validation
  patternError: string | null;
  validatePattern: (pattern: string) => boolean;

  // Preview/test functionality
  previewResult: PreviewResult | null;
  handleTestTrigger: (trigger: NotificationTrigger) => Promise<void>;
  handleViewSession: (error: TriggerTestResult['errors'][0]) => void;
  clearPreview: () => void;

  // Build trigger for testing (used by AddTriggerForm)
  buildTriggerForTest: (formState: {
    name: string;
    contentType: NotificationTrigger['contentType'];
    mode: TriggerMode;
    matchField?: string;
    matchPattern?: string;
    tokenThreshold?: number;
    tokenType?: TriggerTokenType;
    toolName?: string;
    ignorePatterns?: string[];
    repositoryIds?: string[];
  }) => NotificationTrigger;
}

function useTriggerForm(_options: UseTriggerFormOptions = {}): UseTriggerFormReturn {
  const [patternError, setPatternError] = useState<string | null>(null);
  const [previewResult, setPreviewResult] = useState<PreviewResult | null>(null);

  // Get navigateToError from store for View Session functionality
  const navigateToError = useStore((state) => state.navigateToError);

  /**
   * Validate a regex pattern.
   */
  const validatePattern = useCallback((pattern: string): boolean => {
    const error = validateRegexPattern(pattern);
    setPatternError(error);
    return error === null;
  }, []);

  /**
   * Clear the preview result.
   */
  const clearPreview = useCallback(() => {
    setPreviewResult(null);
  }, []);

  /**
   * Test trigger against historical data.
   * Results are automatically limited by the main process to prevent resource exhaustion:
   * - Max 50 errors returned
   * - Max 10,000 totalCount
   * - Max 100 sessions scanned
   * - 30 second timeout
   */
  const handleTestTrigger = useCallback(async (trigger: NotificationTrigger) => {
    setPreviewResult({ loading: true, totalCount: 0, errors: [] });

    try {
      const result = await api.config.testTrigger(trigger);
      setPreviewResult({
        loading: false,
        totalCount: result.totalCount,
        errors: result.errors,
        truncated: result.truncated,
      });
    } catch (error) {
      logger.error('Failed to test trigger:', error);
      setPreviewResult(null);
    }
  }, []);

  /**
   * Handle View Session click - navigate to the error location.
   */
  const handleViewSession = useCallback(
    (error: TriggerTestResult['errors'][0]) => {
      navigateToError({
        id: error.id,
        sessionId: error.sessionId,
        projectId: error.projectId,
        message: error.message,
        timestamp: error.timestamp,
        source: error.source,
        filePath: '',
        context: error.context,
        isRead: true,
        createdAt: error.timestamp,
        // Deep linking data for exact error position
        toolUseId: error.toolUseId,
        subagentId: error.subagentId,
        lineNumber: error.lineNumber,
      });
    },
    [navigateToError]
  );

  /**
   * Build a trigger object from form state for testing.
   */
  const buildTriggerForTest = useCallback(
    (formState: {
      name: string;
      contentType: NotificationTrigger['contentType'];
      mode: TriggerMode;
      matchField?: string;
      matchPattern?: string;
      tokenThreshold?: number;
      tokenType?: TriggerTokenType;
      toolName?: string;
      ignorePatterns?: string[];
      repositoryIds?: string[];
    }): NotificationTrigger => {
      return {
        id: `test-${generateId()}`,
        name: formState.name.trim() || 'Test Trigger',
        enabled: true,
        contentType: formState.contentType,
        mode: formState.mode,
        isBuiltin: false,
        ...(formState.mode === 'error_status' && { requireError: true }),
        ...(formState.mode === 'content_match' &&
          formState.matchField && { matchField: formState.matchField as TriggerMatchField }),
        ...(formState.mode === 'content_match' &&
          formState.matchPattern && { matchPattern: formState.matchPattern }),
        ...(formState.mode === 'token_threshold' && {
          tokenThreshold: formState.tokenThreshold,
          tokenType: formState.tokenType,
        }),
        ...((formState.contentType === 'tool_use' || formState.contentType === 'tool_result') &&
          formState.toolName && { toolName: formState.toolName }),
        ...(formState.ignorePatterns &&
          formState.ignorePatterns.length > 0 && { ignorePatterns: formState.ignorePatterns }),
        ...(formState.repositoryIds &&
          formState.repositoryIds.length > 0 && { repositoryIds: formState.repositoryIds }),
      };
    },
    []
  );

  return {
    patternError,
    validatePattern,
    previewResult,
    handleTestTrigger,
    handleViewSession,
    clearPreview,
    buildTriggerForTest,
  };
}

interface PreviewResult {
  loading: boolean;
  totalCount: number;
  errors: TriggerTestResult['errors'];
  /**
   * True if results were truncated due to safety limits.
   * When truncated, totalCount may be capped at 10,000.
   */
  truncated?: boolean;
}

interface ModeConfig {
  value: TriggerMode;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
}

interface NotificationTriggerSettingsProps {
  triggers: NotificationTrigger[];
  saving: boolean;
  onUpdateTrigger: (triggerId: string, updates: Partial<NotificationTrigger>) => Promise<void>;
  onAddTrigger: (trigger: Omit<NotificationTrigger, 'isBuiltin'>) => Promise<void>;
  onRemoveTrigger: (triggerId: string) => Promise<void>;
}

function generateId(): string {
  return generateUUID();
}

function getAvailableMatchFields(
  contentType: TriggerContentType,
  toolName?: string
): { value: string; label: string }[] {
  if (contentType === 'tool_result') {
    return [{ value: 'content', label: 'Content' }];
  }

  if (contentType === 'thinking') {
    return [{ value: 'thinking', label: 'Thinking Content' }];
  }

  if (contentType === 'text') {
    return [{ value: 'text', label: 'Text Content' }];
  }

  if (contentType === 'tool_use') {
    switch (toolName) {
      case 'Bash':
        return [
          { value: 'command', label: 'Command' },
          { value: 'description', label: 'Description' },
        ];
      case 'Task':
        return [
          { value: 'description', label: 'Description' },
          { value: 'prompt', label: 'Prompt' },
          { value: 'subagent_type', label: 'Subagent Type' },
        ];
      case 'Read':
      case 'Write':
        return [{ value: 'file_path', label: 'File Path' }];
      case 'Edit':
        return [
          { value: 'file_path', label: 'File Path' },
          { value: 'old_string', label: 'Old String' },
          { value: 'new_string', label: 'New String' },
        ];
      case 'Glob':
        return [
          { value: 'pattern', label: 'Pattern' },
          { value: 'path', label: 'Path' },
        ];
      case 'Grep':
        return [
          { value: 'pattern', label: 'Pattern' },
          { value: 'path', label: 'Path' },
          { value: 'glob', label: 'Glob Filter' },
        ];
      case 'WebFetch':
        return [
          { value: 'url', label: 'URL' },
          { value: 'prompt', label: 'Prompt' },
        ];
      case 'WebSearch':
        return [{ value: 'query', label: 'Query' }];
      case 'Skill':
        return [
          { value: 'skill', label: 'Skill Name' },
          { value: 'args', label: 'Arguments' },
        ];
      default:
        // "Any Tool" - match against the entire JSON-serialized input
        return [{ value: '', label: 'Full Input (JSON)' }];
    }
  }

  return [];
}

function deriveMode(trigger: NotificationTrigger): TriggerMode {
  if (trigger.mode) return trigger.mode;
  // Backward compatibility: if requireError is true and no mode, default to error_status
  if (trigger.requireError && trigger.contentType === 'tool_result') {
    return 'error_status';
  }
  return 'content_match';
}

function validateRegexPattern(pattern: string): string | null {
  if (!pattern) {
    return null;
  }
  try {
    new RegExp(pattern);
    return null;
  } catch {
    return 'Invalid regex pattern';
  }
}

