interface PaneSlice {
  // State
  paneLayout: PaneLayout;

  // Pane lifecycle
  focusPane: (paneId: string) => void;
  splitPane: (sourcePaneId: string, tabId: string, direction: 'left' | 'right') => void;
  closePane: (paneId: string) => void;

  // Tab movement
  moveTabToPane: (
    tabId: string,
    sourcePaneId: string,
    targetPaneId: string,
    insertIndex?: number
  ) => void;
  moveTabToNewPane: (
    tabId: string,
    sourcePaneId: string,
    adjacentPaneId: string,
    direction: 'left' | 'right'
  ) => void;
  reorderTabInPane: (paneId: string, fromIndex: number, toIndex: number) => void;

  // Resize
  resizePanes: (paneId: string, newWidthFraction: number) => void;

  // Queries
  getPaneForTab: (tabId: string) => string | null;
  getAllPaneTabs: () => Tab[];
}

function syncRootState(layout: PaneLayout): Record<string, unknown> {
  const synced = syncFocusedPaneState(layout);
  return {
    paneLayout: layout,
    openTabs: synced.openTabs,
    activeTabId: synced.activeTabId,
    selectedTabIds: synced.selectedTabIds,
  };
}

createPaneSlice: StateCreator<AppState, [], [], PaneSlice> = (set, get) => ({
  // Initial state: single pane (populated by tabSlice init or first openTab)
  paneLayout: {
    panes: [
      {
        id: 'pane-default',
        tabs: [],
        activeTabId: null,
        selectedTabIds: [],
        widthFraction: 1,
      },
    ],
    focusedPaneId: 'pane-default',
  },

  focusPane: (paneId: string) => {
    const state = get();
    const { paneLayout } = state;
    if (paneLayout.focusedPaneId === paneId) return;

    const pane = findPane(paneLayout, paneId);
    if (!pane) return;

    const newLayout: PaneLayout = { ...paneLayout, focusedPaneId: paneId };
    set(syncRootState(newLayout));

    // Trigger sidebar sync for the focused pane's active tab
    if (pane.activeTabId) {
      get().setActiveTab(pane.activeTabId);
    }
  },

  splitPane: (sourcePaneId: string, tabId: string, direction: 'left' | 'right') => {
    const state = get();
    const { paneLayout } = state;

    if (paneLayout.panes.length >= MAX_PANES) return;

    const sourcePane = findPane(paneLayout, sourcePaneId);
    if (!sourcePane) return;

    const tab = sourcePane.tabs.find((t) => t.id === tabId);
    if (!tab) return;

    // Remove tab from source pane
    const newSourceTabs = sourcePane.tabs.filter((t) => t.id !== tabId);
    let newSourceActiveTabId = sourcePane.activeTabId;
    if (sourcePane.activeTabId === tabId) {
      // Focus adjacent tab in source
      const oldIndex = sourcePane.tabs.findIndex((t) => t.id === tabId);
      newSourceActiveTabId = newSourceTabs[oldIndex]?.id ?? newSourceTabs[oldIndex - 1]?.id ?? null;
    }

    const updatedSource = {
      ...sourcePane,
      tabs: newSourceTabs,
      activeTabId: newSourceActiveTabId,
      selectedTabIds: sourcePane.selectedTabIds.filter((id) => id !== tabId),
    };

    // Create new pane with the tab
    const newPaneId = generateUUID();
    const newPane = {
      ...createEmptyPane(newPaneId),
      tabs: [tab],
      activeTabId: tab.id,
    };

    // Update layout
    let newLayout = updatePane(paneLayout, updatedSource);

    // If source pane is now empty, remove it
    if (newSourceTabs.length === 0 && paneLayout.panes.length > 1) {
      newLayout = removePane(newLayout, sourcePaneId);
    }

    newLayout = insertPane(
      newLayout,
      updatedSource.id !== sourcePaneId ? paneLayout.panes[0].id : sourcePaneId,
      newPane,
      direction
    );
    newLayout = { ...newLayout, focusedPaneId: newPaneId };

    set(syncRootState(newLayout));

    // Sync sidebar for the new pane's active tab
    if (tab.type === 'session') {
      get().setActiveTab(tab.id);
    }
  },

  closePane: (paneId: string) => {
    const state = get();
    const { paneLayout } = state;

    if (paneLayout.panes.length <= 1) return; // Can't close the last pane

    const pane = findPane(paneLayout, paneId);
    if (!pane) return;

    // Cleanup tab UI state for all tabs in the pane
    for (const tab of pane.tabs) {
      state.cleanupTabUIState(tab.id);
    }

    const newLayout = removePane(paneLayout, paneId);
    set(syncRootState(newLayout));

    // Sync sidebar for the newly focused pane
    const focusedPane = findPane(newLayout, newLayout.focusedPaneId);
    if (focusedPane?.activeTabId) {
      get().setActiveTab(focusedPane.activeTabId);
    }
  },

  moveTabToPane: (
    tabId: string,
    sourcePaneId: string,
    targetPaneId: string,
    insertIndex?: number
  ) => {
    const state = get();
    const { paneLayout } = state;

    if (sourcePaneId === targetPaneId) return;

    const sourcePane = findPane(paneLayout, sourcePaneId);
    const targetPane = findPane(paneLayout, targetPaneId);
    if (!sourcePane || !targetPane) return;

    const tab = sourcePane.tabs.find((t) => t.id === tabId);
    if (!tab) return;

    // Remove from source
    const newSourceTabs = sourcePane.tabs.filter((t) => t.id !== tabId);
    let newSourceActiveTabId = sourcePane.activeTabId;
    if (sourcePane.activeTabId === tabId) {
      const oldIndex = sourcePane.tabs.findIndex((t) => t.id === tabId);
      newSourceActiveTabId = newSourceTabs[oldIndex]?.id ?? newSourceTabs[oldIndex - 1]?.id ?? null;
    }

    // Add to target at insertion index
    const newTargetTabs = [...targetPane.tabs];
    if (insertIndex !== undefined && insertIndex >= 0 && insertIndex <= newTargetTabs.length) {
      newTargetTabs.splice(insertIndex, 0, tab);
    } else {
      newTargetTabs.push(tab);
    }

    let newLayout = updatePane(paneLayout, {
      ...sourcePane,
      tabs: newSourceTabs,
      activeTabId: newSourceActiveTabId,
      selectedTabIds: sourcePane.selectedTabIds.filter((id) => id !== tabId),
    });
    newLayout = updatePane(newLayout, {
      ...targetPane,
      tabs: newTargetTabs,
      activeTabId: tab.id,
    });

    // Auto-close source pane if it's empty and not the sole pane
    if (newSourceTabs.length === 0 && newLayout.panes.length > 1) {
      newLayout = removePane(newLayout, sourcePaneId);
    }

    // Focus the target pane
    newLayout = { ...newLayout, focusedPaneId: targetPaneId };

    set(syncRootState(newLayout));
  },

  moveTabToNewPane: (
    tabId: string,
    sourcePaneId: string,
    adjacentPaneId: string,
    direction: 'left' | 'right'
  ) => {
    const state = get();
    const { paneLayout } = state;

    if (paneLayout.panes.length >= MAX_PANES) return;

    const sourcePane = findPane(paneLayout, sourcePaneId);
    if (!sourcePane) return;

    const tab = sourcePane.tabs.find((t) => t.id === tabId);
    if (!tab) return;

    // Remove from source
    const newSourceTabs = sourcePane.tabs.filter((t) => t.id !== tabId);
    let newSourceActiveTabId = sourcePane.activeTabId;
    if (sourcePane.activeTabId === tabId) {
      const oldIndex = sourcePane.tabs.findIndex((t) => t.id === tabId);
      newSourceActiveTabId = newSourceTabs[oldIndex]?.id ?? newSourceTabs[oldIndex - 1]?.id ?? null;
    }

    const newPaneId = generateUUID();
    const newPane = {
      ...createEmptyPane(newPaneId),
      tabs: [tab],
      activeTabId: tab.id,
    };

    let newLayout = updatePane(paneLayout, {
      ...sourcePane,
      tabs: newSourceTabs,
      activeTabId: newSourceActiveTabId,
      selectedTabIds: sourcePane.selectedTabIds.filter((id) => id !== tabId),
    });

    // Auto-close source pane if it's empty and not the sole pane
    if (newSourceTabs.length === 0 && newLayout.panes.length > 1) {
      newLayout = removePane(newLayout, sourcePaneId);
    }

    newLayout = insertPane(newLayout, adjacentPaneId, newPane, direction);
    newLayout = { ...newLayout, focusedPaneId: newPaneId };

    set(syncRootState(newLayout));
  },

  reorderTabInPane: (paneId: string, fromIndex: number, toIndex: number) => {
    const { paneLayout } = get();
    const pane = findPane(paneLayout, paneId);
    if (!pane) return;

    if (fromIndex < 0 || fromIndex >= pane.tabs.length) return;
    if (toIndex < 0 || toIndex >= pane.tabs.length) return;
    if (fromIndex === toIndex) return;

    const newTabs = [...pane.tabs];
    const [moved] = newTabs.splice(fromIndex, 1);
    newTabs.splice(toIndex, 0, moved);

    const newLayout = updatePane(paneLayout, { ...pane, tabs: newTabs });
    set(syncRootState(newLayout));
  },

  resizePanes: (paneId: string, newWidthFraction: number) => {
    const { paneLayout } = get();
    const paneIndex = paneLayout.panes.findIndex((p) => p.id === paneId);
    if (paneIndex === -1 || paneIndex >= paneLayout.panes.length - 1) return;

    const MIN_FRACTION = 0.1;
    const clamped = Math.max(
      MIN_FRACTION,
      Math.min(1 - MIN_FRACTION * (paneLayout.panes.length - 1), newWidthFraction)
    );
    const currentPane = paneLayout.panes[paneIndex];
    const nextPane = paneLayout.panes[paneIndex + 1];
    const combinedWidth = currentPane.widthFraction + nextPane.widthFraction;
    const nextWidth = combinedWidth - clamped;

    if (nextWidth < MIN_FRACTION) return;

    const newPanes = paneLayout.panes.map((p, i) => {
      if (i === paneIndex) return { ...p, widthFraction: clamped };
      if (i === paneIndex + 1) return { ...p, widthFraction: nextWidth };
      return p;
    });

    set({ paneLayout: { ...paneLayout, panes: newPanes } });
  },

  getPaneForTab: (tabId: string) => {
    const pane = findPaneByTabId(get().paneLayout, tabId);
    return pane?.id ?? null;
  },

  getAllPaneTabs: () => {
    return getAllTabs(get().paneLayout);
  },
})

src/renderer/store/slices/projectSlice.t.source_code:
interface SessionCacheEntry {
  sessions: Session[];
  cursor: string | null;
  hasMore: boolean;
  totalCount: number;
  timestamp: number;
}

interface ProjectSlice {
  // State
  projects: Project[];
  selectedProjectId: string | null;
  projectsLoading: boolean;
  projectsError: string | null;
  _sessionCache: Map<string, SessionCacheEntry>;

  // Actions
  fetchProjects: () => Promise<void>;
  selectProject: (id: string) => void;
}

createProjectSlice: StateCreator<AppState, [], [], ProjectSlice> = (set, get) => ({
  // Initial state
  projects: [],
  selectedProjectId: null,
  projectsLoading: false,
  projectsError: null,
  _sessionCache: new Map(),

  // Fetch all projects from main process
  fetchProjects: async () => {
    set({ projectsLoading: true, projectsError: null });
    try {
      const projects = await api.getProjects();
      // Sort by most recent session (descending)
      const sorted = [...projects].sort(
        (a, b) => (b.mostRecentSession ?? 0) - (a.mostRecentSession ?? 0)
      );
      set({ projects: sorted, projectsLoading: false });
    } catch (error) {
      set({
        projectsError: error instanceof Error ? error.message : 'Failed to fetch projects',
        projectsLoading: false,
      });
    }
  },

  // Select a project and fetch its sessions (paginated)
  selectProject: (id: string) => {
    const cached = get()._sessionCache.get(id);

    if (cached) {
      set({
        selectedProjectId: id,
        sidebarCollapsed: false,
        sessions: cached.sessions,
        sessionsCursor: cached.cursor,
        sessionsHasMore: cached.hasMore,
        sessionsTotalCount: cached.totalCount,
        sessionsLoading: false,
        sessionsError: null,
        selectedSessionId: null,
        sessionDetail: null,
        sessionContextStats: null,
        sessionDetailError: null,
      });
      // Invalidate stale cache so fetchSessionsInitial() overwrites with fresh data
      get()._sessionCache.delete(id);
    } else {
      set({
        selectedProjectId: id,
        sidebarCollapsed: false,
        ...getSessionResetState(),
      });
    }

    // Always fetch fresh data (background refresh when cached)
    void get().fetchSessionsInitial(id);
  },
})

src/renderer/store/slices/repositorySlic.source_code:
interface RepositorySlice {
  // State
  repositoryGroups: RepositoryGroup[];
  selectedRepositoryId: string | null;
  selectedWorktreeId: string | null;
  repositoryGroupsLoading: boolean;
  repositoryGroupsError: string | null;
  viewMode: 'flat' | 'grouped';

  // Actions
  fetchRepositoryGroups: () => Promise<void>;
  selectRepository: (repositoryId: string) => void;
  selectWorktree: (worktreeId: string) => void;
  setViewMode: (mode: 'flat' | 'grouped') => void;
}

createRepositorySlice: StateCreator<AppState, [], [], RepositorySlice> = (
  set,
  get
) => ({
  // Initial state
  repositoryGroups: [],
  selectedRepositoryId: null,
  selectedWorktreeId: null,
  repositoryGroupsLoading: false,
  repositoryGroupsError: null,
  viewMode: 'grouped', // Default to grouped view

  // Fetch all repository groups (projects grouped by git repo)
  fetchRepositoryGroups: async () => {
    set({ repositoryGroupsLoading: true, repositoryGroupsError: null });
    try {
      const groups = await api.getRepositoryGroups();
      // Already sorted by most recent session in the scanner
      set({ repositoryGroups: groups, repositoryGroupsLoading: false });
    } catch (error) {
      set({
        repositoryGroupsError:
          error instanceof Error ? error.message : 'Failed to fetch repository groups',
        repositoryGroupsLoading: false,
      });
    }
  },

  // Select a repository group and auto-select a worktree
  selectRepository: (repositoryId: string) => {
    const { repositoryGroups } = get();
    const repo = repositoryGroups.find((r) => r.id === repositoryId);

    if (!repo) {
      logger.warn('Repository not found:', repositoryId);
      return;
    }

    // Auto-select worktree:
    // 1. Prefer the "Default" worktree (isMainWorktree = true)
    // 2. Otherwise, select the first worktree (already sorted by most recent)
    const defaultWorktree = repo.worktrees.find((w) => w.isMainWorktree);
    const worktreeToSelect = defaultWorktree ?? repo.worktrees[0];

    if (worktreeToSelect) {
      set({
        selectedRepositoryId: repositoryId,
        selectedWorktreeId: worktreeToSelect.id,
        selectedProjectId: worktreeToSelect.id,
        activeProjectId: worktreeToSelect.id,
        sidebarCollapsed: false, // Ensure session list is visible when a project is selected
        ...getSessionResetState(),
      });
      // Fetch sessions for this worktree
      void get().fetchSessionsInitial(worktreeToSelect.id);
    } else {
      // No worktrees available (shouldn't happen normally)
      set({
        selectedRepositoryId: repositoryId,
        selectedWorktreeId: null,
        ...getSessionResetState(),
      });
    }
  },

  // Select a worktree within a repository group
  selectWorktree: (worktreeId: string) => {
    set({
      selectedWorktreeId: worktreeId,
      selectedProjectId: worktreeId,
      activeProjectId: worktreeId,
      ...getSessionResetState(),
    });

    // Fetch sessions for this worktree
    void get().fetchSessionsInitial(worktreeId);
  },

  // Toggle between flat and grouped view modes
  setViewMode: (mode: 'flat' | 'grouped') => {
    set({
      viewMode: mode,
      selectedRepositoryId: null,
      selectedWorktreeId: null,
      selectedProjectId: null,
      ...getSessionResetState(),
    });

    // Fetch the appropriate data for the new mode
    if (mode === 'grouped') {
      void get().fetchRepositoryGroups();
    } else {
      void get().fetchProjects();
    }
  },
})

