function isAbsolutePath(path: string): boolean {
  return (
    path.startsWith('/') ||
    path.startsWith('~/') ||
    path.startsWith('~\\') ||
    path === '~' ||
    path.startsWith('\\\\') ||
    /^[a-zA-Z]:[\\/]/.test(path)
  );
}

