function formatTokensCompact(tokens: number): string {
  if (tokens >= 1000000) {
    return `${(tokens / 1000000).toFixed(1)}M`;
  }
  if (tokens >= 1000) {
    return `${(tokens / 1000).toFixed(1)}k`;
  }
  return tokens.toString();
}

function formatTokens(tokens: number): string {
  if (tokens < 1000) {
    return `${tokens}`;
  }
  if (tokens < 10000) {
    return `${(tokens / 1000).toFixed(1)}k`;
  }
  return `${Math.round(tokens / 1000)}k`;
}

function formatTokensDetailed(tokens: number): string {
  return tokens.toLocaleString();
}

src/shared/utils/tokenFormatting.ts::est.source_code:
function estimateTokens(text: string | undefined | null): number {
  if (!text || text.length === 0) {
    return 0;
  }
  return Math.ceil(text.length / 4);
}

function estimateContentTokens(
  content: string | unknown[] | Record<string, unknown> | undefined | null
): number {
  if (!content) {
    return 0;
  }

  if (typeof content === 'string') {
    return estimateTokens(content);
  }

  // For array/object content, stringify and count
  return estimateTokens(JSON.stringify(content));
}

